create table if not exists clients (id uuid primary key default gen_random_uuid(), name text not null, phone text, created_at timestamptz not null default now(), unique(name, phone));
create table if not exists dashboard_audit_reports (id uuid primary key default gen_random_uuid(), client_id uuid references clients(id), report_json jsonb not null, created_at timestamptz not null default now());
create table if not exists approved_corrections (id uuid primary key default gen_random_uuid(), audit_report_ref uuid references dashboard_audit_reports(id), directory text not null, field text not null, current_value text, proposed_value text, approved_by text not null, approved_at timestamptz not null default now());
create table if not exists write_consents (id uuid primary key default gen_random_uuid(), audit_report_ref uuid references dashboard_audit_reports(id), directory text not null, fields_to_change jsonb not null, consented_by text not null, consented_at timestamptz not null default now());
create table if not exists write_jobs (id uuid primary key default gen_random_uuid(), audit_report_ref uuid references dashboard_audit_reports(id), directory text not null, field text not null, current_value text, proposed_value text, status text not null check (status in ('PENDING','IN_PROGRESS','SUCCESS','FAILED','NEEDS_USER_INPUT')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), error_message text);
create table if not exists writeback_audit_log (id uuid primary key default gen_random_uuid(), write_job_id uuid references write_jobs(id), directory text not null, field text not null, before_value text, after_value text, executed_at timestamptz not null default now(), executed_by_system text not null, outcome text not null, error_message text);
create table if not exists gbp_connections (id uuid primary key default gen_random_uuid(), client_id uuid references clients(id), location_name text not null, encrypted_tokens text not null, created_at timestamptz not null default now(), unique(client_id, location_name));
